import { openai, supabase } from '../config.js';
import { improveUserPrompts } from './improveUserPrompts.js';

/*
  Create an embedding from the user input and return a 
  semantically matching text chunk from the database 
*/
export default async function queryMovieEmbeddings(input) {
    const queryPrompt = await improveUserPrompts(input);
    // Create a vector embedding representing the input text
    const embeddingResponse = await openai.embeddings.create({
        model: process.env.EMBEDDING_LARGE,
        input: queryPrompt,
    }); 
  
    // The vector generated by OpenAI
    const embedding = embeddingResponse.data[0].embedding;
  
    // Query Supabase for nearest vector match
    const { data } = await supabase.rpc('match_movies_large', {
        query_embedding: embedding,
        match_threshold: 0.1,
        match_count: 4
    });

    let output = `Query: ${queryPrompt}\n\n`;
    if (data.length === 0) {
        return `${output}No results found.`;
    }

    data.forEach((movie, index) => 
        output += `${movie.content} ${movie.similarity}${index === data.length - 1 ? '' : '\n\n'}` // 
    )
    return { queryResults: output };
}
